-- Phase 91: Enterprise Portfolio Management control plane.
-- Projects, goals, budgets, capacity, risks, changes and architecture remain canonical in their source modules.
-- quality: allow-nonconcurrent-index reason=new-empty-enterprise-portfolio-tables

create type public.portfolio_context_type as enum('masterapp_internal_portfolio','tenant_enterprise_portfolio');

alter table public.plans add column if not exists enterprise_portfolio_management_enabled boolean not null default false,add column if not exists portfolio_scenario_planning_enabled boolean not null default false,add column if not exists benefit_realization_enabled boolean not null default false,add column if not exists portfolio_capacity_planning_enabled boolean not null default false;
alter table public.store_feature_flags add column if not exists enterprise_portfolio_management_enabled boolean not null default false,add column if not exists portfolio_scenario_planning_enabled boolean not null default false,add column if not exists benefit_realization_enabled boolean not null default false,add column if not exists portfolio_capacity_planning_enabled boolean not null default false;

create table public.portfolio_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permission_key text not null,scope_refs text[] not null default '{}',granted_at timestamptz not null default now(),unique(organization_id,user_id,permission_key));
create table public.portfolio_strategic_themes(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,description text not null default '',status text not null default 'active' check(status in('draft','active','retired')),owner_ref text,created_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)),unique(context_type,organization_id,name));
create table public.portfolio_demands(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,title text not null,description text not null default '',demand_type text not null check(demand_type in('strategic_growth','operational_improvement','revenue_growth','cost_reduction','risk_reduction','compliance_internal','continuity','architecture_modernization','technical_debt','customer_experience','expansion','mandatory','innovation','custom')),source_domain text not null,source_ref text,requester_ref text not null,sponsor_ref text,scope jsonb not null default '{}',status text not null default 'submitted' check(status in('submitted','triage','evaluating','accepted','rejected','deferred','converted_to_initiative','archived')),triage_evidence jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)));
create table public.portfolio_programs(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,program_key text not null,name text not null,description text not null default '',owner_ref text,status text not null default 'proposed' check(status in('proposed','active','on_hold','completed','cancelled','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)),unique(context_type,organization_id,program_key));
create table public.portfolio_initiatives(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,initiative_key text not null,name text not null,description text not null default '',initiative_type text not null check(initiative_type in('transformation','modernization','risk_remediation','growth','efficiency','expansion','resilience','platform','operational','mandatory')),sponsor_ref text,owner_ref text,strategic_theme_id uuid references public.portfolio_strategic_themes(id) on delete set null,program_id uuid references public.portfolio_programs(id) on delete set null,source_demand_id uuid references public.portfolio_demands(id) on delete set null,status text not null default 'proposed' check(status in('proposed','discovery','business_case','approved','funded','planned','executing','on_hold','completed','cancelled','rejected')),priority_class text,health_dimensions jsonb not null default '{}',target_start date,target_end date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)),check(target_end is null or target_start is null or target_end>=target_start),unique(context_type,organization_id,initiative_key));
create table public.initiative_project_links(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,project_id uuid references public.internal_projects(id) on delete restrict,source_project_ref text,link_status text not null default 'confirmed' check(link_status in('candidate','confirmed','rejected','historical')),created_at timestamptz not null default now(),check(project_id is not null or source_project_ref is not null));
create table public.initiative_change_links(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,change_id uuid not null references public.change_requests(id) on delete restrict,link_status text not null default 'confirmed' check(link_status in('candidate','confirmed','rejected','historical')),created_at timestamptz not null default now(),unique(initiative_id,change_id));
create table public.initiative_risk_links(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,risk_id uuid not null references public.enterprise_risks(id) on delete restrict,link_status text not null default 'confirmed' check(link_status in('candidate','confirmed','rejected','historical')),treatment_ref text,created_at timestamptz not null default now(),unique(initiative_id,risk_id));
create table public.initiative_capability_links(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,capability_id uuid not null references public.business_capabilities(id) on delete restrict,link_status text not null default 'confirmed' check(link_status in('candidate','confirmed','rejected','historical')),gap_ref text,target_state_ref text,created_at timestamptz not null default now(),unique(initiative_id,capability_id));
create table public.initiative_goal_links(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,goal_id uuid not null references public.performance_goals(id) on delete restrict,link_status text not null default 'confirmed' check(link_status in('candidate','confirmed','rejected','historical')),created_at timestamptz not null default now(),unique(initiative_id,goal_id));

create table public.initiative_business_cases(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,version integer not null check(version>0),problem_statement text not null,current_state text not null default '',target_state text not null default '',options_considered jsonb not null default '[]',recommended_option text,assumptions jsonb not null default '[]',estimated_cost numeric,estimate_quality text not null default 'unknown' check(estimate_quality in('rough_order_of_magnitude','preliminary','validated','committed','unknown')),currency text,estimated_benefits jsonb not null default '[]',financial_methodology text not null default 'no_financial_model' check(financial_methodology in('simple_roi','payback_period','npv','irr','total_cost','no_financial_model')),discount_rate numeric,nonfinancial_benefits jsonb not null default '[]',risks jsonb not null default '[]',dependencies jsonb not null default '[]',owner_ref text not null,status text not null default 'draft' check(status in('draft','review','approved','rejected','superseded')),valid_until date,created_at timestamptz not null default now(),unique(initiative_id,version),check(estimated_cost is null or currency is not null));
create table public.portfolio_benefit_estimates(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,business_case_id uuid references public.initiative_business_cases(id) on delete set null,organization_id uuid references public.organizations(id) on delete cascade,benefit_type text not null check(benefit_type in('revenue','margin','cost_saving','cost_avoidance','risk_reduction','capacity','cycle_time','customer_experience','reliability','strategic','compliance_internal','qualitative')),baseline numeric,expected_change numeric,unit text,period text,source text,confidence text not null default 'unknown' check(confidence in('high','medium','low','unknown')),owner_ref text not null,currency text,assumptions jsonb not null default '[]',created_at timestamptz not null default now(),check(benefit_type='qualitative' or expected_change is null or unit is not null));

create table public.portfolio_prioritization_frameworks(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,version integer not null check(version>0),criteria jsonb not null check(jsonb_typeof(criteria)='array'),gating_rules jsonb not null default '[]',scales jsonb not null default '{}',status text not null default 'draft' check(status in('draft','active','retired')),policy_ref text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)),unique(context_type,organization_id,name,version));
create table public.portfolio_prioritization_assessments(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,framework_id uuid not null references public.portfolio_prioritization_frameworks(id) on delete restrict,framework_version integer not null,criterion text not null,rating numeric not null,evidence jsonb not null default '{}',rationale text not null,assessor_ref text not null,assessed_at timestamptz not null default now(),unique(initiative_id,framework_id,framework_version,criterion));
create table public.portfolio_dependencies(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,dependency_type text not null check(dependency_type in('initiative_requires_initiative','initiative_requires_project','capability_dependency','architecture_dependency','funding_dependency','external_dependency','change_dependency')),strength text not null check(strength in('hard','soft','sequencing','shared_resource')),depends_on_initiative_id uuid references public.portfolio_initiatives(id) on delete restrict,depends_on_ref text,status text not null default 'active' check(status in('active','satisfied','waived','cancelled')),created_at timestamptz not null default now(),check(depends_on_initiative_id is not null or depends_on_ref is not null),check(depends_on_initiative_id is null or depends_on_initiative_id<>initiative_id));

create table public.portfolio_capacity_plans(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('team','function','domain','region')),scope_ref text not null,period_start date not null,period_end date not null,unit text not null,available_capacity numeric not null check(available_capacity>=0),committed_capacity numeric not null default 0 check(committed_capacity>=0),source_ref text,confidence text not null default 'unknown' check(confidence in('high','medium','low','unknown')),created_at timestamptz not null default now(),check(period_end>=period_start),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)));
create table public.initiative_capacity_requirements(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('team','function','domain','region')),scope_ref text not null,period_start date not null,period_end date not null,required_capacity numeric not null check(required_capacity>=0),unit text not null,confidence text not null default 'unknown' check(confidence in('high','medium','low','unknown')),created_at timestamptz not null default now(),check(period_end>=period_start));
create table public.portfolio_funding_requests(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,funding_period text not null,funding_type text not null,requested_amount numeric not null check(requested_amount>=0),approved_amount numeric check(approved_amount is null or approved_amount>=0),currency text not null,source_budget_ref text not null,status text not null default 'draft' check(status in('draft','requested','approved','partially_approved','deferred','rejected','released')),approval_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table public.portfolio_scenarios(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,scenario_type text not null check(scenario_type in('base_plan','constrained_budget','aggressive_growth','risk_first','reliability_first','expansion_focus','custom')),version integer not null default 1,assumptions jsonb not null default '{}',budget_envelope jsonb not null default '{}',capacity_envelope jsonb not null default '{}',framework_id uuid references public.portfolio_prioritization_frameworks(id) on delete set null,status text not null default 'draft' check(status in('draft','ready','running','completed','failed','archived')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)),unique(context_type,organization_id,name,version));
create table public.portfolio_scenario_runs(id uuid primary key default gen_random_uuid(),scenario_id uuid not null references public.portfolio_scenarios(id) on delete cascade,organization_id uuid references public.organizations(id) on delete cascade,status text not null default 'queued' check(status in('queued','running','completed','failed')),objective text not null default 'transparent_rule_based_portfolio',constraints jsonb not null default '[]',result_summary jsonb not null default '{}',calculation_trace jsonb not null default '[]',started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table public.portfolio_scenario_items(id uuid primary key default gen_random_uuid(),scenario_run_id uuid not null references public.portfolio_scenario_runs(id) on delete cascade,initiative_id uuid not null references public.portfolio_initiatives(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,outcome text not null check(outcome in('fund','defer','blocked','mandatory','optional')),reasons jsonb not null default '[]',budget_used numeric,capacity_used jsonb not null default '{}',tradeoffs jsonb not null default '[]',created_at timestamptz not null default now(),unique(scenario_run_id,initiative_id));
create table public.portfolio_roadmaps(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,granularity text not null check(granularity in('month','quarter','year')),status text not null default 'proposed' check(status in('proposed','approved','active','superseded')),horizon_start date,horizon_end date,created_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)));
create table public.portfolio_roadmap_items(id uuid primary key default gen_random_uuid(),roadmap_id uuid not null references public.portfolio_roadmaps(id) on delete cascade,initiative_id uuid not null references public.portfolio_initiatives(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,horizon text check(horizon in('current','next','future')),starts_on date,ends_on date,project_timeline_ref text,swimlane_type text,swimlane_ref text,created_at timestamptz not null default now());

create table public.benefit_realization_plans(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete restrict,benefit_estimate_id uuid not null references public.portfolio_benefit_estimates(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,baseline numeric,target numeric,unit text,measurement_metric_ref text,target_date date not null,owner_ref text not null,attribution_type text not null default 'unknown' check(attribution_type in('direct','shared','estimated','unknown')),realization_status text not null default 'planned' check(realization_status in('planned','measuring','on_track','at_risk','realized','partially_realized','not_realized','unknown')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.benefit_realization_measurements(id uuid primary key default gen_random_uuid(),benefit_plan_id uuid not null references public.benefit_realization_plans(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,period text not null,actual numeric,baseline numeric,target numeric,data_quality text not null default 'unknown' check(data_quality in('certified','validated','limited','unknown')),source_metric text,evidence jsonb not null default '{}',measured_at timestamptz not null default now(),unique(benefit_plan_id,period));
create table public.initiative_value_reviews(id uuid primary key default gen_random_uuid(),initiative_id uuid not null references public.portfolio_initiatives(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,review_date date not null,expected_cost numeric,actual_cost numeric,currency text,expected_benefits jsonb not null default '[]',realized_benefits jsonb not null default '[]',schedule_outcome jsonb not null default '{}',risk_reduction jsonb not null default '{}',capability_impact jsonb not null default '{}',lessons jsonb not null default '[]',created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.portfolio_reviews(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,review_type text not null check(review_type in('monthly','quarterly','annual','ad_hoc')),period_start date,period_end date,status text not null default 'draft' check(status in('draft','prepared','in_review','completed','archived')),review_pack jsonb not null default '{}',decisions_needed jsonb not null default '[]',created_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)));
create table public.portfolio_decisions(id uuid primary key default gen_random_uuid(),initiative_id uuid references public.portfolio_initiatives(id) on delete restrict,organization_id uuid references public.organizations(id) on delete cascade,decision_type text not null check(decision_type in('fund','defer','cancel','accelerate','reduce_scope','hold','re_evaluate')),decision text not null,rationale text not null,decision_maker_ref text not null,approval_ref text,scenario_ref uuid references public.portfolio_scenarios(id) on delete set null,decided_at timestamptz not null default now(),safe_metadata jsonb not null default '{}');
create table public.portfolio_governance_policies(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,policy_engine_ref text not null,scope jsonb not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)));
create table public.portfolio_baselines(id uuid primary key default gen_random_uuid(),context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,name text not null,version integer not null check(version>0),status text not null default 'approved' check(status in('approved','superseded')),snapshot jsonb not null,content_hash text not null,approval_ref text not null,published_by uuid references auth.users(id),published_at timestamptz not null default now(),check((context_type='tenant_enterprise_portfolio' and organization_id is not null)or(context_type='masterapp_internal_portfolio' and organization_id is null)),unique(context_type,organization_id,name,version),unique(context_type,organization_id,content_hash));
create table public.portfolio_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,job_type text not null check(job_type in('scenario','capacity_refresh','benefit_refresh','coverage_refresh','review_pack','health_check')),status text not null default 'queued' check(status in('queued','running','completed','failed','dead_letter')),payload jsonb not null default '{}',attempt_count integer not null default 0,available_at timestamptz not null default now(),lease_expires_at timestamptz,error_message text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.portfolio_audit_events(id bigint generated always as identity primary key,context_type public.portfolio_context_type not null,organization_id uuid references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id) on delete set null,action text not null,resource_type text not null,resource_id text,correlation_id text,safe_metadata jsonb not null default '{}',created_at timestamptz not null default now());

create function public.prevent_portfolio_dependency_cycle() returns trigger language plpgsql set search_path=public as $$begin if new.depends_on_initiative_id is null then return new; end if;if exists(with recursive chain(id) as(select new.depends_on_initiative_id union select d.depends_on_initiative_id from public.portfolio_dependencies d join chain c on d.initiative_id=c.id where d.depends_on_initiative_id is not null and d.status='active')select 1 from chain where id=new.initiative_id)then raise exception 'PORTFOLIO_DEPENDENCY_CYCLE';end if;return new;end$$;
create trigger portfolio_dependency_cycle before insert or update on public.portfolio_dependencies for each row execute function public.prevent_portfolio_dependency_cycle();
create function public.prevent_portfolio_history_rewrite() returns trigger language plpgsql set search_path=public as $$begin raise exception 'PORTFOLIO_HISTORY_IMMUTABLE';end$$;
create trigger portfolio_decisions_immutable before update or delete on public.portfolio_decisions for each row execute function public.prevent_portfolio_history_rewrite();
create trigger portfolio_baselines_immutable before update or delete on public.portfolio_baselines for each row execute function public.prevent_portfolio_history_rewrite();
revoke all on function public.prevent_portfolio_dependency_cycle() from public,anon,authenticated;grant execute on function public.prevent_portfolio_dependency_cycle() to service_role;
revoke all on function public.prevent_portfolio_history_rewrite() from public,anon,authenticated;grant execute on function public.prevent_portfolio_history_rewrite() to service_role;

create index portfolio_demands_inbox_idx on public.portfolio_demands(context_type,organization_id,status,created_at desc);
create index portfolio_initiatives_status_idx on public.portfolio_initiatives(context_type,organization_id,status,priority_class);
create index portfolio_dependencies_from_idx on public.portfolio_dependencies(initiative_id,status,strength);
create index portfolio_dependencies_to_idx on public.portfolio_dependencies(depends_on_initiative_id,status,strength) where depends_on_initiative_id is not null;
create index portfolio_capacity_period_idx on public.portfolio_capacity_plans(context_type,organization_id,scope_type,scope_ref,period_start,period_end);
create index portfolio_capacity_requirements_idx on public.initiative_capacity_requirements(organization_id,scope_type,scope_ref,period_start,period_end);
create index portfolio_funding_status_idx on public.portfolio_funding_requests(organization_id,status,funding_period);
create index portfolio_scenario_jobs_idx on public.portfolio_jobs(status,available_at,lease_expires_at);
create index portfolio_benefit_status_idx on public.benefit_realization_plans(organization_id,realization_status,target_date);
create index portfolio_audit_lookup_idx on public.portfolio_audit_events(context_type,organization_id,created_at desc);

create view public.enterprise_portfolio_overview with(security_invoker=true) as select context_type,organization_id,count(*) filter(where status in('approved','funded','planned','executing')) active_initiatives,count(*) filter(where status='funded') funded_initiatives,count(*) filter(where status='on_hold') blocked_or_on_hold from public.portfolio_initiatives group by context_type,organization_id;

do $$declare t text;begin foreach t in array array['portfolio_member_permissions','portfolio_strategic_themes','portfolio_demands','portfolio_programs','portfolio_initiatives','initiative_project_links','initiative_change_links','initiative_risk_links','initiative_capability_links','initiative_goal_links','initiative_business_cases','portfolio_benefit_estimates','portfolio_prioritization_frameworks','portfolio_prioritization_assessments','portfolio_dependencies','portfolio_capacity_plans','initiative_capacity_requirements','portfolio_funding_requests','portfolio_scenarios','portfolio_scenario_runs','portfolio_scenario_items','portfolio_roadmaps','portfolio_roadmap_items','benefit_realization_plans','benefit_realization_measurements','initiative_value_reviews','portfolio_reviews','portfolio_decisions','portfolio_governance_policies','portfolio_baselines','portfolio_jobs','portfolio_audit_events'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
revoke all on public.enterprise_portfolio_overview from public,anon,authenticated;grant select on public.enterprise_portfolio_overview to service_role;

insert into public.feature_definitions(feature_key,name,description,category,value_type,default_value,safe_default,client_safe,owner_label,lifecycle_status,created_at,updated_at) values
('enterprise_portfolio_management_enabled','Enterprise Portfolio Management','Ativa demandas, iniciativas e governança de portfólio.','governance','boolean','false','false',false,'Enterprise Portfolio','active',now(),now()),('portfolio_scenario_planning_enabled','Portfolio Scenario Planning','Ativa simulações transparentes de orçamento e capacidade.','governance','boolean','false','false',false,'Enterprise Portfolio','active',now(),now()),('benefit_realization_enabled','Benefit Realization','Ativa planos e medições de benefícios separados da conclusão do projeto.','governance','boolean','false','false',false,'Enterprise Portfolio','active',now(),now()),('portfolio_capacity_planning_enabled','Portfolio Capacity Planning','Ativa capacidade agregada por equipe, função, domínio e região.','governance','boolean','false','false',false,'Enterprise Portfolio','active',now(),now()) on conflict(feature_key) do update set name=excluded.name,description=excluded.description,updated_at=now();

