insert into public.search_command_registry(id,title,description,keywords,command_type,route,action_type,required_permission,risk_level,scope,position) values('go-enterprise-portfolio','Abrir Portfólio Estratégico','Abrir visão de portfólio',array['portfolio','investimentos'],'navigation','/painel/estrategia/portfolio',null,'portfolio:view','low','organization',125),('new-portfolio-demand','Nova demanda','Abrir intake de demanda estratégica',array['nova demanda','ideia','iniciativa'],'navigation','/painel/estrategia/portfolio?tab=Demandas',null,'portfolio:create_demand','low','organization',126),('compare-portfolio-scenarios','Comparar cenários','Abrir o Scenario Builder',array['cenario','comparar','corte orcamento'],'navigation','/painel/estrategia/portfolio?tab=Cenários',null,'portfolio:run_scenarios','low','organization',127),('view-portfolio-blockers','Ver iniciativas bloqueadas','Abrir dependências do portfólio',array['bloqueadas','dependencias'],'navigation','/painel/estrategia/portfolio?tab=Dependências',null,'portfolio:view','low','organization',128),('view-investment-gaps','Ver gaps sem investimento','Abrir cobertura estratégica',array['gaps','risco','capability'],'navigation','/painel/estrategia/portfolio?tab=Analytics',null,'portfolio:view','low','organization',129),('view-benefits-at-risk','Ver benefícios em risco','Abrir realização de benefícios',array['beneficios','risco'],'navigation','/painel/estrategia/portfolio?tab=Benefícios',null,'portfolio:manage_benefits','low','organization',130) on conflict(id) do update set title=excluded.title,description=excluded.description,keywords=excluded.keywords,command_type=excluded.command_type,route=excluded.route,action_type=excluded.action_type,required_permission=excluded.required_permission,risk_level=excluded.risk_level,scope=excluded.scope,position=excluded.position;
